# towers.py

class Tower:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.damage = 10
        self.range = 100

    def draw(self, screen):
        pygame.draw.circle(screen, (0, 255, 0), (self.x, self.y), 20)

# enemies.py

import pygame

class Enemy:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.health = 50
        self.speed = 1

    def move(self):
        self.x += self.speed

    def draw(self, screen):
        pygame.draw.rect(screen, (255, 0, 0), (self.x, self.y, 20, 20))

# stages.py

import pygame
from enemies import Enemy

class Stage:
    def __init__(self, waves):
        self.waves = waves
        self.current_wave = 0
        self.enemies = []

    def spawn_enemies(self):
        if self.current_wave < len(self.waves):
            wave = self.waves[self.current_wave]
            for enemy_data in wave:
                enemy_type = enemy_data['type']
                enemy_count = enemy_data['count']
                for _ in range(enemy_count):
                    if enemy_type == 'basic':
                        enemy = Enemy(0, 50)
                        self.add_enemy(enemy)
            self.current_wave += 1

    def add_enemy(self, enemy):
        self.enemies.append(enemy)

    def update(self):
        for enemy in self.enemies:
            enemy.move()

    def draw(self, screen):
        for enemy in self.enemies:
            enemy.draw(screen)

